import json, os

base = "/Users/kristinarash/Library/Caches/sportsci-batch-100"
tax = json.load(open(os.path.join(base, "taxonomy.json"), encoding="utf-8"))
inputs = {p["id"]: p for p in json.load(open(os.path.join(base, "inputs.json"), encoding="utf-8"))}
ids = ["Q25", "Q26", "Q27", "Q28", "Q29", "Q30", "Q31", "Q32"]

for i in ids:
    path = os.path.join(base, "drafts", i + ".json")
    raw = open(path, encoding="utf-8").read()
    problems = []
    if "—" in raw:
        problems.append("em dash present")
    d = json.loads(raw)
    if d["id"] != i:
        problems.append("id mismatch")
    if d["sourceFile"] != inputs[i]["sourceFile"]:
        problems.append("sourceFile mismatch")
    if d["decision"] == "INCLUDE":
        if d["primaryDomain"] not in d["domains"]:
            problems.append("primaryDomain not in domains")
        for k, allowed in [("domains", tax["domains"]), ("audiences", tax["audiences"]),
                           ("sports", tax["sports"]), ("populations", tax["populations"])]:
            for v in d[k]:
                if v not in allowed:
                    problems.append(k + " bad value: " + v)
        if d["primaryDomain"] not in tax["domains"]:
            problems.append("primaryDomain bad")
        if d["studyDesign"] not in tax["studyDesigns"]:
            problems.append("studyDesign bad")
        if d["paper"]["doi"] not in raw:
            problems.append("doi not in draft")
        if not d["paper"]["doi"].startswith("10."):
            problems.append("doi prefix")
    print(i, d["decision"], d["paper"]["year"] if d.get("paper") else "-", "OK" if not problems else problems)

